//! Differential policy evidence generated by Core's synthetic Node oracle.
#![allow(clippy::unwrap_used, clippy::indexing_slicing)]
use embedding_worker::media_policy::{
    needs_figures, tail_candidate, tail_window, upload_candidate,
};
use serde_json::Value;
#[test]
fn node_candidate_and_progress_formats() {
    let fixture: Value = serde_json::from_str(include_str!("fixtures/media-u2-node.json")).unwrap();
    for case in fixture["candidates"].as_array().unwrap() {
        let file = &case["file"];
        assert_eq!(
            needs_figures(file, &case["record"]),
            case["figures"].as_bool().unwrap(),
            "{}",
            case["name"]
        );
        assert_eq!(
            upload_candidate(file, "old"),
            case["upload"].as_bool().unwrap(),
            "{}",
            case["name"]
        );
        assert_eq!(
            tail_candidate(
                file,
                4,
                file["content"]
                    .as_str()
                    .unwrap_or("")
                    .encode_utf16()
                    .count()
            ),
            case["tail"].as_bool().unwrap(),
            "{}",
            case["name"]
        );
    }
}
#[test]
fn node_page_windows() {
    let fixture: Value = serde_json::from_str(include_str!("fixtures/media-u2-node.json")).unwrap();
    for case in fixture["windows"].as_array().unwrap() {
        // These small pages each produce one unchanged RAG chunk. The real
        // chunker belongs to the source-indexing dependency, not this policy.
        let result = tail_window(
            case["content"].as_str().unwrap(),
            &case["record"],
            &case["options"],
            |text| text.split("\n\n").map(str::to_owned).collect(),
        );
        assert_eq!(result, case["result"], "{}", case["name"]);
    }
}
#[test]
fn node_settings() {
    let fixture: Value = serde_json::from_str(include_str!("fixtures/media-u2-node.json")).unwrap();
    for case in fixture["settings"].as_array().unwrap() {
        let got = embedding_worker::media_policy::settings(&case["env"]);
        for (key, value) in case["result"].as_object().unwrap() {
            assert_eq!(got[key].as_f64(), value.as_f64(), "{key}");
        }
    }
}
